def copy_studio_fk_to_links(apps, schema_editor):
    Anime = apps.get_model("anime", "Anime")
    AnimeStudio = apps.get_model("anime", "AnimeStudio")
    AnimeStudio.objects.bulk_create(
        (
            AnimeStudio(anime_id=anime_id, studio_id=studio_id, position=0)
            for anime_id, studio_id in Anime.objects.filter(studio__isnull=False)
            .values_list("id", "studio_id")
            .iterator()
        ),
        batch_size=1000,
    )


LEGACY_JIKAN_ANILIST_ID_OFFSET = 1_500_000_000


def clear_fake_anilist_ids(apps, schema_editor):
    """Jikan rows used to store MAL_ID + 1.5e9 as a fake AniList ID. Store NULL instead.

    The MAL ID is recovered from the fake ID when the row has none. A row whose MAL ID
    already belongs to another row is a shadow duplicate: it keeps no IDs and is
    quarantined so it stays hidden, as public_queryset() used to do.
    """
    Anime = apps.get_model("anime", "Anime")
    OfflineAnimeSyncState = apps.get_model("anime", "OfflineAnimeSyncState")

    fake_rows = Anime.objects.filter(anilist_id__gte=LEGACY_JIKAN_ANILIST_ID_OFFSET)
    for anime in fake_rows.only("id", "anilist_id", "mal_id").iterator():
        decoded_mal_id = anime.anilist_id - LEGACY_JIKAN_ANILIST_ID_OFFSET
        anime.anilist_id = None
        shadow_of = None
        if anime.mal_id is None:
            shadow_of = (
                Anime.objects.filter(mal_id=decoded_mal_id).values_list("id", flat=True).first()
            )
            if shadow_of is None:
                anime.mal_id = decoded_mal_id
        anime.save(update_fields=["anilist_id", "mal_id"])

        if shadow_of is not None:
            OfflineAnimeSyncState.objects.update_or_create(
                anime_id=anime.id,
                defaults={
                    "quarantined": True,
                    "quarantine_reason": "shadow_duplicate",
                    "quarantine_context": {"mal_id": decoded_mal_id, "canonical_id": shadow_of},
                },
            )


def copy_links_to_studio_fk(apps, schema_editor):
    Anime = apps.get_model("anime", "Anime")
    AnimeStudio = apps.get_model("anime", "AnimeStudio")
    for link in AnimeStudio.objects.filter(position=0).iterator():
        Anime.objects.filter(id=link.anime_id).update(studio_id=link.studio_id)


